fn emit_responses_websocket_timing_event(
    kind: &str,
    payload: &str,
    context: &ResponsesWebsocketTimingLogContext,
) {
    if kind != RESPONSES_WEBSOCKET_TIMING_KIND {
        return;
    }

    // This full payload is excluded from always-on sinks. Opt in with
    // `RUST_LOG='codex_api::responses_websocket_timing=trace'`.
    tracing::event!(
        name: RESPONSES_WEBSOCKET_TIMING_KIND,
        target: RESPONSES_WEBSOCKET_TIMING_EVENT_TARGET,
        tracing::Level::TRACE,
        model = context.model.as_str(),
        session_id = context.session_id.as_deref().unwrap_or_default(),
        thread_id = context.thread_id.as_deref().unwrap_or_default(),
        turn_id = context.turn_id.as_deref().unwrap_or_default(),
        traceparent = context.traceparent.as_deref().unwrap_or_default(),
        previous_response_id = context.previous_response_id.as_deref().unwrap_or_default(),
        request_start_ms = context.request_start_ms.as_deref().unwrap_or_default(),
        warmup = context.warmup,
        connection_reused = context.connection_reused,
        payload,
        "responses websocket timing"
    );

pub fn record_responses(&self, handle_responses_span: &Span, event: &ResponseEvent) {
    handle_responses_span.record("otel.name", SessionTelemetry::responses_type(event));

    match event {
        ResponseEvent::OutputItemDone(item) => {
            handle_responses_span.record("from", "output_item_done");
            if let ResponseItem::FunctionCall { name, .. } = item {
                handle_responses_span.record("tool_name", name.as_str());
            }
        }
        ResponseEvent::OutputItemAdded(item) => {
            handle_responses_span.record("from", "output_item_added");
            if let ResponseItem::FunctionCall { name, .. } = item {
                handle_responses_span.record("tool_name", name.as_str());
            }
        }
        ResponseEvent::Completed {
            token_usage: Some(token_usage),
            ..
        } => {
            handle_responses_span.record("gen_ai.usage.input_tokens", token_usage.input_tokens);
            handle_responses_span.record(
                "gen_ai.usage.cache_read.input_tokens",
                token_usage.cached_input(),
            );
            handle_responses_span.record(
                "gen_ai.usage.cache_write.input_tokens",
                token_usage.cache_write_input_tokens,
            );
            handle_responses_span
                .record("gen_ai.usage.output_tokens", token_usage.output_tokens);
            handle_responses_span.record(
                "codex.usage.reasoning_output_tokens",
                token_usage.reasoning_output_tokens,
            );
            handle_responses_span.record("codex.usage.total_tokens", token_usage.total_tokens);
        }
        _ => {}
    }

pub fn record_websocket_event(
    &self,
    result: &Result<
        Option<
            Result<
                tokio_tungstenite::tungstenite::Message,
                tokio_tungstenite::tungstenite::Error,
            >,
        >,
        ApiError,
    >,
    duration: Duration,
) {
    let mut kind = None;
    let mut success = true;

    match result {
        Ok(Some(Ok(message))) => match message {
            tokio_tungstenite::tungstenite::Message::Text(text) => {
                match serde_json::from_str::<serde_json::Value>(text) {
                    Ok(value) => {
                        kind = value
                            .get("type")
                            .and_then(|value| value.as_str())
                            .map(std::string::ToString::to_string);
                        if kind.as_deref() == Some(RESPONSES_WEBSOCKET_TIMING_KIND) {
                            self.record_responses_websocket_timing_metrics(&value);
                        }
                        if kind.as_deref() == Some("response.failed") {
                            success = false;
                        }
                    }
                    Err(_) => {
                        kind = Some("parse_error".to_string());
                        success = false;
                    }
                }
            }
            tokio_tungstenite::tungstenite::Message::Ping(_)
            | tokio_tungstenite::tungstenite::Message::Pong(_) => {
                return;
            }
            tokio_tungstenite::tungstenite::Message::Binary(_)
            | tokio_tungstenite::tungstenite::Message::Close(_)
            | tokio_tungstenite::tungstenite::Message::Frame(_) => {
                success = false;
            }
        },
        Ok(Some(Err(_))) | Ok(None) | Err(_) => {
            success = false;
        }
    }

    let kind_str = kind.as_deref().unwrap_or(WEBSOCKET_UNKNOWN_KIND);
    let success_str = if success { "true" } else { "false" };
    let tags = [("kind", kind_str), ("success", success_str)];
    self.counter(WEBSOCKET_EVENT_COUNT_METRIC, /*inc*/ 1, &tags);
    self.record_duration(WEBSOCKET_EVENT_DURATION_METRIC, duration, &tags);
}

